#define HP_LANE_RAW_STREAM_RSP_BYTES 2U

/* ---- 0x28 LANE_CALIBRATE (request) -------------------------------
 * LEARN: the lanes in laneMask (bit n-1 = lane n) learn their bare-foil level (lanes must be free) and the control module saves it as each lane's reference. FORGET drops the saved references. The response only acknowledges; each lane's outcome follows as EVT_LANE_CALIBRATED.
 */

/* LANE_CALIBRATE request */
typedef struct __attribute__((packed)) {
    uint8_t laneMask;
    uint8_t action;   /* hpCalibrateAction_e */
} hpLaneCalibrateReq_t;
_Static_assert(sizeof(hpLaneCalibrateReq_t) == 2U, "hpLaneCalibrateReq_t layout");
#define HP_LANE_CALIBRATE_REQ_BYTES 2U

/* LANE_CALIBRATE response */
typedef struct __attribute__((packed)) {
    int16_t status; /* ctrlStatus_e. On error the payload is this field only. */
} hpLaneCalibrateRsp_t;
_Static_assert(sizeof(hpLaneCalibrateRsp_t) == 2U, "hpLaneCalibrateRsp_t layout");
#define HP_LANE_CALIBRATE_RSP_BYTES 2U

/* ---- 0x40 START_SEQUENCE (request) -------------------------------
 * Start: from T0 all lights breathe in unison (attentionPulses off-on-off cycles, pulseRiseMs per half), the last chain lane stays lit at the last peak, then one more lane lights every stepMs toward lane 1; with all lit, a random hold in [holdMin, holdMax], then all go out together at Tout. EVT_SEQ_STARTED now, EVT_LIGHTS_OUT at Tout (never earlier).
 */

/* START_SEQUENCE request */
typedef struct __attribute__((packed)) {
    uint8_t  lights;          /* 1..6; lanes present are lit in index order */
    uint8_t  armSampling;     /* 1 = also switch sampling ON at T0 */
    uint16_t stepMs;
    uint16_t holdMinMs;
    uint16_t holdMaxMs;
    uint16_t leadMs;          /* Time from now to T0; 0 = default (>= 150 ms) */
    uint16_t pulseRiseMs;     /* Attention pulse: off to full in this many ms; 0 = default 1000 */
    uint8_t  attentionPulses; /* Off-on-off cycles before the countdown; 0 = none */
    uint8_t  reserved;
} hpStartSequenceReq_t;
_Static_assert(sizeof(hpStartSequenceReq_t) == 14U, "hpStartSequenceReq_t layout");
#define HP_START_SEQUENCE_REQ_BYTES 14U

/* START_SEQUENCE response */
typedef struct __attribute__((packed)) {
    int16_t  status;   /* ctrlStatus_e. On error the payload is this field only. */
    uint16_t reserved;
    uint64_t t0Us;     /* System time the first light goes on */
} hpStartSequenceRsp_t;
_Static_assert(sizeof(hpStartSequenceRsp_t) == 12U, "hpStartSequenceRsp_t layout");
#define HP_START_SEQUENCE_RSP_BYTES 12U

/* ---- 0x41 ABORT_SEQUENCE (request) -------------------------------
 * Cancels the running start sequence: lanes' pending actions cancelled, lights blink, EVT_SEQ_ABORTED.
 */

/* ABORT_SEQUENCE request: empty payload */
